const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0 || input[0] === '') return;

    const N = parseInt(input[0], 10);
    const V = [];
    for (let i = 1; i <= N; i++) {
        V.push(parseInt(input[i], 10));
    }

    if (N <= 2) {
        console.log(N);
        return;
    }

    // Coleta as posições de cada número
    const positions = new Map();
    for (let i = 0; i < N; i++) {
        const val = V[i];
        if (!positions.has(val)) {
            positions.set(val, []);
        }
        positions.get(val).push(i);
    }

    const uniqueVals = Array.from(positions.keys());

    // Se só tem 1 número distinto
    if (uniqueVals.length <= 1) {
        console.log(uniqueVals.length);
        return;
    }

    let maxLen = 1;

    for (let i = 0; i < uniqueVals.length; i++) {
        const u = uniqueVals[i];
        const posU = positions.get(u);

        for (let j = i + 1; j < uniqueVals.length; j++) {
            const v = uniqueVals[j];
            const posV = positions.get(v);

            // Mesclar as posições de u e v mantendo a alternância
            let p1 = 0, p2 = 0;
            let last = 0;
            let currentLen = 0;

            while (p1 < posU.length && p2 < posV.length) {
                if (posU[p1] < posV[p2]) {
                    if (last !== u) {
                        currentLen++;
                        last = u;
                    }
                    p1++;
                } else {
                    if (last !== v) {
                        currentLen++;
                        last = v;
                    }
                    p2++;
                }
            }

            while (p1 < posU.length) {
                if (last !== u) {
                    currentLen++;
                    last = u;
                }
                p1++;
            }

            while (p2 < posV.length) {
                if (last !== v) {
                    currentLen++;
                    last = v;
                }
                p2++;
            }

            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
        }
    }

    console.log(maxLen);
}

solve();
